@page {
  size: 80mm 50mm;
}
.tp-label {
  border: 1px solid #111827;
  box-sizing: border-box;
  color: #111827;
  font-size: 9px;
  height: 48mm;
  padding: 4mm;
  position: relative;
  width: 78mm;
}
.tp-label-main {
  padding-right: 28mm;
}
.tp-label h1 {
  font-size: 16px;
  margin: 0 0 2mm;
}
.tp-label p {
  margin: 1mm 0;
}
.tp-label img {
  height: 24mm;
  position: absolute;
  right: 4mm;
  top: 4mm;
  width: 24mm;
}
.tp-url {
  bottom: 3mm;
  font-size: 6px;
  left: 4mm;
  position: absolute;
  right: 4mm;
  word-break: break-all;
}
